using System.Collections.Generic;

namespace AncientWarfare3.content.figures
{
    internal static class HistoricalFigureCardBiographiesSuiTang
    {
        public static void AddTo(IDictionary<string, string> pEntries)
        {
            pEntries.Add("an_lushan",
                "安禄山（703年2月19日—757年1月25日），本姓康，名轧荦山，营州柳城（今辽宁省朝阳市）人。父为昭武九姓的粟特人，母为突厥巫师，信仰祆教。安禄山是唐代藩镇割据势力之一的最初建立者，也是安史之乱的主要发动人之一，后建立大燕政权，自称雄武皇帝，年号圣武。此卡以安禄山建立燕政权并称帝后的君主身份为核心，重点落在叛军政权的统治与覆亡。");
            pEntries.Add("chen_houzhudi",
                "陈叔宝（553年12月10日—604年12月16日），字元秀，小字黄奴，南北朝时期陈朝末代皇帝（582年2月20日－589年2月10日在位），史称“陈后主”，在位共7年，年号太建（即位沿用）、至德、祯明。好声色，工诗词，不恤朝政。隋灭陈后被俘，病死于洛阳。所作《玉树后庭花》等词，历代视为「亡国之音」。");
            pEntries.Add("da_zuorong",
                "渤海高王（？—719年4月2日），讳大祚荣，是渤海国的开国之主，在位期从698年至719年。根据《旧唐书》和《新唐书》的记载：姓「大」氏，粟末靺鞨部（满洲先祖）人，亦是“渤海靺鞨大祚荣为高丽别种”，粟末靺鞨酋长乞乞仲象之子（一说大祚荣和乞乞仲象是同一人）。曾依附于高句丽，高句丽被新罗联合中国唐朝所灭，后脱离中国武周朝，创立渤海国（震国）。");
            pEntries.Add("dong_chang",
                "董昌在唐末黄巢之乱期间组织地方武装，凭守卫杭州之功逐步控制浙东，并任威胜军节度使。他后来在越州自立为帝，国号大越罗平，滥施封赏和酷刑以维持统治。钱镠奉唐廷之命出兵讨伐，八九六年攻破越州，董昌被俘后身亡。");
            pEntries.Add("dou_jiande",
                "窦建德（573年—621年8月3日），贝州漳南县（今河北省衡水市故城县东北）人。隋末民变领袖之一，于乐寿称王改元。后在虎牢之战中兵败被俘，遭斩首于长安。");
            pEntries.Add("du_fuwei",
                "杜伏威（583年—623年5月2日），名尧，字伏威，以字行，齐州章丘县（今山东省济南市章丘区）人。隋朝末期农民起义军领导者之一。自幼家贫，惯于偷盗，与辅公祏是刎颈之交。辅公祏常从姑家里偷羊送给杜伏威吃。");
            pEntries.Add("fu_gongshi",
                "辅公祏（？—624年），中国隋朝末年民变军领袖之一，齐郡临济（今山东章丘）人。辅公祏与杜伏威交好，姑家以牧羊为业，常从姑家偷羊给杜伏威吃。613年随从杜伏威率众据长白山（今章丘、邹平交界处）起兵，杜伏威自称将军。");
            pEntries.Add("gao_kaidao",
                "高开道（？—624年），赐姓李时为李开道，隋末农民起义领袖，在怀戎（今河北张家口）依附突厥称燕王。高开道是沧州阳信人，年轻时，煮海水贩卖私盐。有勇力，跑起来像奔马一样。");
            pEntries.Add("huang_chao",
                "黄巢（835年—884年），曹州冤句（今山东菏泽西南）人，大齐开国君主。初为盐帮首领，售私盐为业，后成为反抗大唐的民变军首领，并自立为帝，尊号为承天应运启圣睿文宣武皇帝，国号大齐，年号金统。他发动的民变史称“黄巢之乱”。");
            pEntries.Add("li_gui",
                "李轨（583年—619年），字处则，武威郡姑臧县（在今甘肃省武威市）人，其祖籍郡望出自赵郡李氏，后家族落武威籍，随以武威为郡望。隋末唐初时期河西地区割据者。隋朝大业中，补鹰扬府司兵。大业十三年（617年），李轨自称河西大凉王，建元安乐，武德元年（618年），唐高祖李渊为了进攻薛举，遣使给李轨送来玺书，称李轨为从弟。");
            pEntries.Add("li_mi",
                "李密（582年—619年1月20日），字玄邃，一字法主，长安人，祖籍辽东襄平（今辽宁辽阳）。为人好学，曾把书挂在牛角上，骑着牛读书，人称「牛角挂书」，早年为杨玄感的幕僚与好友，玄感败死，加入瓦岗军继续起义，一度势力极大，曾与唐王李渊结义。后因被王世充偷袭，归降李渊，因怀疑李渊即将加害自己而逃遁，被唐将盛彦师所杀。");
            pEntries.Add("li_xilie",
                "李希烈原为淮西节度使李忠臣部将，发动兵变驱逐李忠臣后接管淮西军镇，并逐步兼并周边州县。唐德宗削藩时他公开反叛，攻陷汴州后称楚帝，年号武成，又杀害奉命劝降的颜真卿。唐军与地方藩镇持续反攻，李希烈部众离散，最终被部将陈仙奇毒杀，其割据政权随即瓦解。");
            pEntries.Add("li_zitong",
                "李子通（？—622年）是中国隋代末年唐朝初年领袖之一，东海丞（今山东峄县）人，渔民出身。大业末年，李投奔盗左才相，因李子通声望日高为其所忌，因而离去；又投奔杜伏威，后在海陵（今江苏泰州）自立。619年击败陈棱，攻克江都，自称皇帝，建国号吴，年号明政。次年击败沈法兴，攻取京口、丹阳、毗陵等郡都归附。");
            pEntries.Add("liang_shidu",
                "梁师都（570年—628年），夏州朔方（今陕西省靖边县北白城子）人。隋末唐初割据政权梁国君主。梁师都他出身于当地豪族，仕隋后官拜鹰扬郎将。617年杀郡丞唐世宗，称大丞相起兵自立。");
            pEntries.Add("lin_shihong",
                "林士弘（6世纪？—622年），饶州鄱阳县（今江西鄱阳县）人，隋末唐初地方割据势力之一。隋炀帝大业十二年（616年）随同乡操师乞率众起兵，攻占豫章郡城，师乞战死后他统率义军大败隋军于鄱阳湖，杀隋将刘子翊，发展到十多万人，遂攻占虔州（在今江西省赣州市境），林士弘称南越王或楚帝，并用延康或太平为年号；其势力最强时领土由江西九江至广东广州。后来与梁帝萧铣多次交战，势力衰落，本来归附他的冯盎等也转投萧铣。后来萧铣被唐朝所灭，一些部众归顺林士弘，林士弘势力复振。");
            pEntries.Add("liu_wuzhou",
                "刘武周（6世纪—620年），河间郡景城县（今河北省沧州市沧县）人，隋朝末年地方割据势力。刘武周的父亲迁居马邑（今山西朔州）。刘武周骁勇善骑射，喜结交豪侠，后前往洛阳，投奔太仆杨义臣。大业八年至十年（612年—614年）间，应募三度北伐高句丽，以军功任建节校尉，还马邑，为鹰扬府校尉（隋朝府兵系统的基层军官）。");
            pEntries.Add("pi_luoge",
                "皮逻阁（？—748年），又作皮罗阁、魁乐觉，蒙舍诏第五代诏，是南诏第一代国王，盛逻皮之子，以唐赐名为谥，称归义王，作蒙归义。728年，盛逻皮病逝，皮罗阁继位，大败东洱海蛮，设立河东州。729年2月，唐朝打败吐蕃，攻下昆明盐源（今云南盐源）。");
            pEntries.Add("shen_faxing",
                "沈法兴（？—621年），湖州武康人。隋末地方官员，隋末民变时称王。大业十四年（618年），隋炀帝被宇文化及所杀。沈法兴以诛宇文化及为名，从东阳郡起兵。毗陵郡通守路道德率兵拒绝，沈法兴请求与连和，会盟时袭杀路道德，进据其城（今江苏常州），自称梁王，建都毗陵，改元延康。");
            pEntries.Add("sui_an_lushan",
                "安禄山（703年2月19日—757年1月25日），本姓康，名轧荦山，营州柳城（今辽宁省朝阳市）人。父为昭武九姓的粟特人，母为突厥巫师，信仰祆教。安禄山是唐代藩镇割据势力之一的最初建立者，也是安史之乱的主要发动人之一，后建立大燕政权，自称雄武皇帝，年号圣武。此卡以安禄山身为唐朝节度使、掌控范阳平卢河东兵权的臣将阶段为核心，重点落在起兵前的扩张。");
            pEntries.Add("sui_bai_juyi",
                "白居易（772年2月28日—846年9月8日），字乐天，晚号香山居士、醉吟先生，在诗界有广大教化主的称号。祖籍山西太原，生于河南新郑，唐代文学家，文章精切，特别擅长写诗，是中唐最具代表性的诗人之一。作品平易近人、通俗易懂，乃至于有「老妪能解」的说法。白居易早年积极从事政治改革，关怀民生，倡导新乐府运动，主张诗歌创作不能离开现实，须取材于现实事件，反映时代的状况，所谓「文章合为时而着，歌诗合为事而作」，是继杜甫之后实际派文学的重要领袖人物之一。");
            pEntries.Add("sui_cen_wenben",
                "岑文本（595年—645年5月10日），字景仁，南阳郡棘阳县（今新野县）人。隋唐时代政治人物、文学家，唐初贞观朝的宰相，封爵江陵子。于隋末萧铣在江陵建立地方政权时，即任岑为中书侍郎，专职管理典藏文书。唐太宗当朝以后，先任秘书郎，复任中书侍郎，并受命与令狐德棻编撰《周书》，文章练达；终官拜中书令，与长孙无忌、高士廉、唐俭、杨师道、刘洎、马周、褚遂良并列宰相团。");
            pEntries.Add("sui_changsun_wuji",
                "长孙无忌（594年？—659年），字辅机，河南郡洛阳县（今河南省洛阳市东）人。唐初大臣和外戚，，封齐国公、赵国公，凌烟阁二十四功臣之首。唐太宗长孙皇后之兄，唐高宗的舅父。高祖李渊武德年间，在李世民还是秦王时，长孙无忌就是李世民的重要顾问。");
            pEntries.Add("sui_cheng_yaojin",
                "程知节（589年—665年2月26日），字义贞，原名咬金，济州东阿人（今属山东省东阿县），唐朝大将，凌烟阁二十四功臣之十九。大部分演义小说以其本名称呼。在民间故事中，他是一员福将，其三板斧相当厉害，但实际上，一生并无以板斧为武器，而用槊。");
            pEntries.Add("sui_chu_suiliang",
                "褚（chǔ）遂良（596年—658年），字登善，杭州钱塘县（今浙江省杭州市）人，祖籍河南郡阳翟县（今河南省禹州市）。封河南郡公，故又世称褚河南，唐朝政治家、书法家。先祖为褚少孙，曾补《史记》。父褚亮博学多才，精通文史。");
            pEntries.Add("sui_di_renjie",
                "狄仁杰（630年—704年），字怀英，并州太原县（今山西省太原市）人，祖籍冯翊郡高陆县（今陕西省西安市高陵区）。为唐朝、武周时的着名宰相。他先后举荐了张柬之、桓彦范、敬晖、窦怀贞及姚崇等数十位干练的官员，皆为唐朝中兴之臣，朝中政风为之一变。史载曾有人对他说：“天下桃李，悉在公门矣。");
            pEntries.Add("sui_du_fu",
                "杜甫（712年－770年），字子美，自号少陵野老，唐朝诗人。其家族出自京兆杜氏分支，祖籍杜陵，出生于河南府巩县。杜甫曾任左拾遗、检校工部员外郎，故后世又称「杜拾遗」「杜工部」。安史之乱期间，他辗转于长安、凤翔、秦州等地，后寓居成都，在浣花溪畔建草堂。");
            pEntries.Add("sui_du_ruhui",
                "杜如晦（585年—630年5月6日），字克明，京兆郡杜陵县（今陕西省西安市长安区）人，唐朝初期大臣。他是李世民夺取政权、开创贞观之治中的主要谋臣之一，深受李世民的重用。与房玄龄被人并称“房谋杜断”。唐太宗时的宰相：贞观二年（628年）正月至三年（629年）二月为侍中，三年二月至十二月为尚书右仆射。");
            pEntries.Add("sui_du_you",
                "杜佑（735年—812年），字君卿，唐代政治家、史学家，京兆万年县（在今中国陕西省西安市境）人，官至宰相，着有通典。杜佑出自中古名族京兆杜氏，杜预次子杜尹之后。曾祖杜行敏是银青光禄大夫、荆益二州大都督府长史、南阳郡公，曾祖杜悫是中散大夫、尚书右司员外郎、详定学士，父亲杜希望是银青光禄大夫、鸿胪卿、恒州刺史、西河郡太守、尚书左仆射。杜佑年十八即以父荫补官，历任济南参军、郯县丞，后入润州（今江苏镇江）刺史韦元甫幕，历官容管经略使、水陆转运使，又做到岭南淮南诸镇节度使，任内推广灌溉，开垦荒田；后又任户部侍郎判度支，时军费开支浩繁，官吏大索商贾，“人不胜苦，有缢死者，长安嚣然如被寇盗”。");
            pEntries.Add("sui_fang_xuanling",
                "房玄龄（579年—648年8月18日），名乔，字玄龄，以字行，其神道碑则作名玄龄。清朝为避圣祖讳，又作房元龄。齐州临淄县（今山东省淄博市临淄区）人，唐朝初年名相、凌烟阁二十四功臣之一。");
            pEntries.Add("sui_gao_jiong",
                "高熲（6世纪—607年8月27日），字昭玄，一名敏，渤海郡蓨县（今河北景县）人，隋朝宰相执政近20年，其子是杨勇的女婿，后因反对废太子杨勇并得罪独孤皇后，遭隋文帝猜忌，被免官为民，不久后又免去齐国公爵位。隋炀帝时，被起用为太常卿。大业三年，见炀帝奢靡，甚为忧虑，有所议论，为人告发，与贺若弼同时被杀害。");
            pEntries.Add("sui_gao_shilian",
                "高士廉（575年—647年2月14日），名俭，字士廉，以字行，渤海蓨县（今河北景县）人。唐代开国功臣，北齐清河王高岳之孙，高劢之子。高士廉，名俭，字士廉，以字行，渤海蓨县（今河北景县）人。出身于官宦之家，其妹为隋右骁卫将军长孙晟之妻，生一子一女，子为长孙无忌，女为长孙氏。");
            pEntries.Add("sui_gongdi",
                "隋恭帝杨侑（605年—619年9月14日），隋炀帝之孙，长子元德太子杨昭嫡子，母为韦妃，皇泰主杨侗之兄。唐高祖李渊所立傀儡皇帝，入唐后改封酅国公。生于大业元年（605年），同年，其父杨昭被立为太子。大业二年（606年），父亲杨昭逝世。");
            pEntries.Add("sui_guo_ziyi",
                "郭子仪（697年—781年7月9日），华州郑县（今陕西渭南市华州区）人，祖籍并州太原，唐代政治家、军事家、名将。唐朝朔方军集团将领，一生平定安史之乱等诸多乱事，历事玄宗、肃宗、代宗、德宗四帝，封汾阳郡王，世称郭令公。为传说“富贵寿考”典故的主人公，颐和园长廊画中有描绘。唐代史学家裴垍评价他：「权倾天下而朝不忌，功盖一代而主不疑，侈穷人慾而君子不之罪。");
            pEntries.Add("sui_han_xiu",
                "韩休（673年—740年6月8日），字良士，京兆长安（今陕西西安）人，唐朝政治人物、宰相。为韩大智次子，十二岁能作文章，十八岁博通群书。弱冠应文笔绝伦科，举擢第一，授冀州下博县尉，黄门侍郎李峤见其文章卓越，改授他为蒲州虞乡县尉。又应制举（由吏部侍郎郑愔主持科举）。");
            pEntries.Add("sui_han_yu",
                "韩愈（768年—824年12月25日），字退之，河南府河阳县（今河南省孟州市）人，自称郡望昌黎，世称韩昌黎；晚年任吏部侍郎，又称韩吏部。唐朝官员、文学家，与柳宗元是当时古文运动的推行者，合称「韩柳」。苏轼称赞他“文起八代之衰，道济天下之溺，忠犯人主之怒，勇夺三军之帅”（八代：东汉、魏、晋、宋、齐、梁、陈、隋）。");
            pEntries.Add("sui_he_zhizhang",
                "贺知章（659年—744年），字季真，一字维摩，号石窗，晚年号四明狂客，越州永兴县（今浙江萧山）人，唐朝诗人、书法家、官员，因曾任秘书监，故人称贺监，官至礼部尚书。三国时东吴将领贺齐的十八世孙。贺知章是史料所载的萧山历史上唯一的状元。贺知章流传下来的诗不多，收录于《全唐诗》中的只有二十首，着名的有《咏柳》、《回乡偶书》等。");
            pEntries.Add("sui_hou_junji",
                "侯君集（？—643年4月29日），豳州三水县（今陕西旬邑北）人，唐朝初期将领。侯君集自少年时代就勇武为人称颂，隋末被李世民引入幕府，因作战有功，累迁左虞侯、车骑将军。唐高祖武德九年（626年）玄武门之变间，他曾为李世民出谋划策。");
            pEntries.Add("sui_li_deyu",
                "李德裕（787年—849年），本名李缄，字文饶，赵州赞皇县（今河北省石家庄市赞皇县）人，出自赵郡李氏西祖，晚唐着名政治家、思想家、文学家，一生历经自唐德宗至唐宣宗共八朝，爵至卫国公，因此别号李卫公，终年六十三岁。李德裕年轻时因抵制贡举制度而随父李吉甫奔波，在京师不久便因裴、李之争贬于地方，出镇浙西、淮南、西川等地，在各地取得了很多政绩。在他从政的四十年中，李德裕也参与了着名的牛李党争，被普遍认定为李党的领袖人物。唐文、武两朝时为李德裕政治的巅峰，这使得牛党受到很大的抑制。");
            pEntries.Add("sui_li_guangbi",
                "李光弼是平定安史之乱的核心将领，与郭子仪齐名。他在太原之战中以严密城防击退史思明，随后参加收复长安、洛阳，并在河阳以少胜多稳定东都防线。晚年李光弼因宦官监军和朝廷猜忌与中枢关系恶化，但其治军和守城能力仍被唐人推为名将典范。");
            pEntries.Add("sui_li_jiang",
                "李绦（764年—830年3月8日），字深之。李绦是进士出身，授秘书省校书郎。元和二年（807年），授翰林学士。为人正直，直言敢谏，唐宪宗称“疾风知劲草，卿当之矣。”贞元末年，拜监察御史，曾言：“天后朝命官猥多，当时有车载斗量之语。");
            pEntries.Add("sui_li_jing",
                "李靖（571年—649年7月2日），字药师，雍州三原县（今陕西省咸阳市三原县东北）人，祖籍陇西郡狄道县（今甘肃省定西市临洮县），出自陇西李氏定着四房之一的丹杨房，隋末唐初名将，是唐朝文武兼备的军事家。后封卫国公，世称李卫公，凌烟阁二十四功臣之一。他的舅舅韩擒虎是隋灭南陈的名将，对这个外甥最为赏识。");
            pEntries.Add("sui_li_keyong",
                "李克用（856年10月24日—908年2月24日），字翼圣，神武川之新城（今山西代县）人，后唐庄宗李存勖之父，本姓朱邪（又作朱耶），其父受唐朝天子赐李姓。绰号鸦儿、三郎、独眼龙、飞虎子，沙陀族人，唐大中十年（856年）生于神武川之新城（在今山西代县北部）。是中国唐朝末年最强大的藩镇节度使之一，后受唐封为晋王。后唐建立后，尊称其为唐太祖武皇帝。");
            pEntries.Add("sui_li_linfu",
                "李林甫（683年—753年1月3日），小名哥奴，号月堂，陕西人。唐朝远房宗室、权臣、奸臣。唐玄宗开元二十二年（734年）五月，出任礼部尚书同中书门下平章事，从此任相十九年。李林甫任相期间主要对唐高宗以来逐渐恶化的冗官现象进行了整顿，并编订《长行旨》改革地方财政，在京师设置常平仓解决长安长期的缺粮情况，编订《唐六典》等。");
            pEntries.Add("sui_li_mi",
                "李泌（722年5月15日—789年4月1日），字长源，京兆人，祖籍辽东襄平，唐朝宰相。生于唐玄宗开元10年（岁次壬戌）四月廿六日（公元722年5月15日），是西魏八柱国李弼的六代孙，父亲李承休是吴房县令，聚书两万余卷，并告诫子孙不得卖书。李泌幼居长安（今西安），七岁能作对句，张説奇之，玄宗召令供奉东宫，写诗讽刺国相杨国忠，有“青青东门柳，岁晏复憔悴。肃宗时，参预军国大议，拜银青光禄大夫，隐居衡山（今湖南省），修炼道教，共十二年。");
            pEntries.Add("sui_li_shiji",
                "李积（594年—669年12月31日），原名徐世积，或作世绩，字懋功，亦作茂功。唐高祖李渊赐其姓李，是为李世积，后避唐太宗李世民讳改名为李积。曹州离狐（今山东省菏泽市东明县东南）人，唐初将领，曾破东突厥、高句丽，与李靖并称。历事唐高祖、唐太宗、唐高宗三朝，深得朝廷信任和重任，朝廷倚之为长城。此卡以获赐李姓后的李世勣名义收录其平定东突厥、攻灭高句丽并辅政唐高宗的名将阶段。");
            pEntries.Add("sui_li_shuo",
                "李硕参与中唐河朔与西北军务，承担军镇联络、部队调度和粮道保护等职责。他所处时期藩镇势力扩张，中央必须依靠熟悉地方军政的将领维持交通与边防。此卡侧重其军职和后勤活动，反映中唐国家在长期边患下维系军事体系的具体方式。");
            pEntries.Add("sui_liu_yan",
                "刘晏（716年—780年），字士安，曹州南华（今山东菏泽市东明）人，历仕唐玄宗、唐肃宗、唐代宗、唐德宗四朝。代宗朝主管全国财政，德宗朝被赐死，后追赠郑州刺史，又加司徒。刘晏幼年以神童着称，开元十三年（725年），唐玄宗封禅泰山，刘晏上《东封书》。玄宗大喜，使中书令张说测试他，竟对答如流。");
            pEntries.Add("sui_liu_zongyuan",
                "柳宗元（773年—819年11月28日），字子厚，，亦称柳河东、柳柳州，唐代中期士大夫、文学家与思想家，古文运动倡导者。柳宗元家势显赫，世代为官。年轻时仕途得意，平步青云，参与王叔文的永贞革新，不幸旋即失败，获罪贬谪永州，自此长期流放，身心寂寞痛苦，十年后改授柳州刺史，卒于官，享年四十六岁。柳宗元以文学、思想、经学、宗教等领域的成就着称。");
            pEntries.Add("sui_lu_huaishen",
                "卢怀慎（？—716年），字怀慎，滑州灵昌县（今河南滑县西南）人，祖籍范阳郡涿县，唐代官员。卢怀慎出自范阳卢氏北祖第三房，祖父卢悊为灵昌令，因此迁居于灵昌。怀慎少年清谨，中进士及第，武则天时历任监察御史、吏部员外郎，唐中宗景龙年间，迁右御史台御史中丞，《旧唐书》载其所上的时政得失三篇。");
            pEntries.Add("sui_ma_zhou",
                "马周（601年—648年2月7日），字宾王，博州茌平人（今属山东），唐朝初年大臣，进士。马周早年孤贫，然熟读诗经和春秋。武德年间，马周一度出任州助教，但因不理政事而被刺史达奚恕指责，遂辞官而去。后至汴州，被浚义令崔贤羞辱，于是西入长安，投入常何门下为门客。");
            pEntries.Add("sui_pei_du",
                "裴度（765年—839年），字中立，河东闻喜县（今山西省运城市闻喜县）人，出自河东裴氏东眷裴。中晚唐时宪宗、穆宗、敬宗、文宗四朝重臣，官至中书令。贞元五年（789年）进士及第，登宏词科，又应贤良方正、能直言极谏科，对策高第，授河阴县尉。唐宪宗元和六年，担任招降魏博节度使田弘正的使节。");
            pEntries.Add("sui_pei_ju",
                "裴矩（547年—627年），字弘大，河东郡闻喜县（今山西闻喜东北）人，隋末及唐初政治家。初名裴世矩，后避太宗名讳，单名矩。祖父，裴佗，北魏荆州刺史，父亲裴讷之，北齐太子舍人，早卒。仕途开始于北齐，为高平王文学。");
            pEntries.Add("sui_pei_xingjian",
                "裴行俭早年从苏定方学习兵法，兼具文官选才与前线统军经验。他先后平定西突厥阿史那都支、护送波斯王子，并以伏兵和招抚结合的方式擒获阿史那伏念。裴行俭善于识拔李多祚、黑齿常之等将领，所著选谱与草书作品也显示其文武兼资。");
            pEntries.Add("sui_qin_qiong",
                "秦琼字叔宝，隋末先后在来护儿、张须陀和裴仁基麾下作战，以勇猛冲阵闻名。裴仁基降瓦岗军后他归李密，瓦岗失败又短暂隶属王世充，最终率部投奔李唐并追随李世民。秦琼参加讨平宋金刚、王世充、窦建德等战役，受封胡国公，去世后名列凌烟阁功臣并与尉迟敬德一同演变为门神形象。");
            pEntries.Add("sui_song_jing",
                "宋璟（663年—737年12月15日），邢州南和县（今河北省邢台市南和区）人，祖籍广平郡列人县（今河北省邯郸市肥乡区），为唐玄宗开元初期宰相。宋璟是北魏吏部尚书宋弁的七代孙，五代祖宋钦道是北齐黄门侍郎，高祖宋元节是定州田曹，曾祖宋宏俊是大理丞，祖父宋务本是唐朝栎阳县县令，父亲宋元抚是卫州司户，因为宋璟显贵赠予邢州刺史、户部尚书。宋璟在17岁时进士及第，可谓年少得志。武后执政后，宋璟被重用，逐步由凤阁舍人（即中书舍人）升迁至御史中丞。此卡侧重宋璟出任宰相后坚持法度、限制权贵请托并整顿开元吏治的经历。");
            pEntries.Add("sui_song_jing_blue",
                "宋璟（663年—737年12月15日），邢州南和县（今河北省邢台市南和区）人，祖籍广平郡列人县（今河北省邯郸市肥乡区），为唐玄宗开元初期宰相。宋璟是北魏吏部尚书宋弁的七代孙，五代祖宋钦道是北齐黄门侍郎，高祖宋元节是定州田曹，曾祖宋宏俊是大理丞，祖父宋务本是唐朝栎阳县县令，父亲宋元抚是卫州司户，因为宋璟显贵赠予邢州刺史、户部尚书。宋璟在17岁时进士及第，可谓年少得志。武后执政后，宋璟被重用，逐步由凤阁舍人（即中书舍人）升迁至御史中丞。此卡侧重宋璟在地方任职、处理选官和刑狱，并由此进入唐朝中枢的仕途阶段。");
            pEntries.Add("sui_su_wei",
                "苏威（542年—623年），字无畏，京兆郡武功县人。父亲苏绰是西魏宇文泰的心腹、苏威5歳时，父亲去世。継承美阳县公（《周书》作美阳伯）的爵位，任郡功曹。北周重臣宇文护礼遇他，想把女儿新兴主嫁给他。");
            pEntries.Add("sui_wei_zheng",
                "魏徵（zhēng）（580年—643年1月17日），字玄成，相州内黄县（今河南省安阳市内黄县）人，祖籍钜鹿郡下曲阳县（今河北省晋州市），隋唐政治家，思想家，文学家和史学家，曾任谏议大夫、左光禄大夫，封郑国公，谥文贞，以直谏敢言着称，是中国史上最负盛名的谏臣，辅佐唐太宗创建“贞观之治”的大业，被后人称为“一代名相”。着有《隋书》序论，《梁书》、《陈书》、《齐书》的总论等。其中《谏太宗十思疏》为最着名并流传下来的谏文表。");
            pEntries.Add("sui_wendi",
                "隋文帝杨坚（541年7月21日—604年8月13日），因父亲杨忠被西魏恭帝赐鲜卑姓，又名普六茹坚，小字那罗延，弘农郡华阴县（今陕西省华阴市）人。隋朝开国皇帝，谥号文皇帝，庙号高祖，581年3月4日－604年8月13日在位，在位24年。杨坚获得的随王封号与相国的大权，并最终在581年使北周静帝禅让于他，建立隋朝。杨坚掌权之后，下令“以前赐姓，皆复其旧”，恢复汉姓“杨”，并让宇文泰鲜卑化政策中改姓的汉人恢复汉姓。");
            pEntries.Add("sui_xu_jingzong",
                "许敬宗（592年—672年9月20日），字延族，浙江新城县（今杭州市富阳区新登镇）人，先祖自高阳南渡，世仕江左。唐朝官员，官至中书令（宰相）。咸亨三年薨，高宗为之举哀、废朝三日，诏文武百官就第赴哭，赠开府仪同三司、扬州大都督，陪葬昭陵。");
            pEntries.Add("sui_xu_shiji",
                "李积（594年—669年12月31日），原名徐世积，或作世绩，字懋功，亦作茂功。唐高祖李渊赐其姓李，是为李世积，后避唐太宗李世民讳改名为李积。曹州离狐（今山东省菏泽市东明县东南）人，唐初将领，曾破东突厥、高句丽，与李靖并称。历事唐高祖、唐太宗、唐高宗三朝，深得朝廷信任和重任，朝廷倚之为长城。此卡以徐世勣名义收录其早年参加瓦岗军、归附李唐并参与统一战争的经历。");
            pEntries.Add("sui_xue_rengui",
                "薛仁贵（614年—683年），名礼，字仁贵，以字行，绦州龙门县（今山西省河津市）人，祖籍河东郡汾阴县（今山西省运城市万荣县）。出自河东薛氏南祖，是北魏将领薛安都的六世孙，唐朝初期将领。于贞观末年参军，随征高丽，留下了三箭定天山等典故。");
            pEntries.Add("sui_xue_song",
                "薛嵩（8世纪？—773年1月17日），字嵩，绦州龙门（今山西河津）人。曾参与安史之乱的叛军，后归顺唐朝，封昭义节度使、平阳郡王。通俗小说《薛刚反唐》的薛刚原型即是薛嵩。");
            pEntries.Add("sui_yan_zhenqing",
                "颜真卿（709年—785年8月23日），字清臣，小名羡门子，别号应方，京兆府长安县（今陕西省西安市）人，祖籍琅邪郡临沂县（今山东省临沂市），唐朝政治家、书法家。其楷书与欧阳询、虞世南、褚遂良、薛曜、薛稷、柳公权在当朝和后世都有极为深远的影响。颜真卿少年丧父，由母亲殷氏（殷践猷之长妹）抚养长大。贫乏纸笔，以黄土扫墙，习学书字，攻楷书绝妙，词翰超伦”。");
            pEntries.Add("sui_yang_guozhong",
                "杨国忠（700年代—756年7月15日），本名杨钊，唐玄宗赐名「国忠」，蒲州永乐（在今山西省永济市和芮城县）人，唐代权臣，与杨贵妃同一曾祖父的从兄（一说同一祖父的堂兄），是为唐朝外戚。玄宗时与李林甫勾结，权倾内外，李林甫死，为宰相，身兼四十余职，家族豪富登天。安禄山、史思明以「诛国忠、清君侧」为名，发动安史之乱。杨国忠随玄宗奔蜀，马嵬之变中被士兵诛杀。");
            pEntries.Add("sui_yang_su",
                "杨素（544年—606年8月31日），字处道，弘农郡华阴县（今陕西省华阴市）人，出自弘农杨氏越公房，北周、隋朝军事家、诗人。杨素，字处道，弘农郡华阴县（今陕西省华阴市）人，出自弘农杨氏越公房，北周、隋朝军事家、诗人。杨素的祖父杨暄是北魏辅国将军、谏议大夫。父亲杨敷是北周汾州刺史，陷没于北齐。");
            pEntries.Add("sui_yangdi",
                "隋炀帝杨广（569年—618年4月11日），又名英，小字阿，隋文帝杨坚和文献皇后独孤伽罗的次子，唐高祖的表弟，是隋朝第二位皇帝。唐高祖李渊谥杨广为炀帝；夏王窦建德谥杨广为闵帝；越王杨侗谥杨广为明帝，庙号世祖。炀帝十三岁被封为晋王，兼任并州总管。隋炀帝为皇子时挂帅消灭南陈，统一中国，后取代兄长杨勇被立为太子，于604年7月21日由杨素协助登基，在位期间加强了中央集权，扩大了统治的社会基础。");
            pEntries.Add("sui_yangtong",
                "杨侗（600年代—619年7月19日），字仁谨，隋炀帝杨广之孙，元德太子杨昭次子，母小刘良娣。留守东都洛阳期间，隋炀帝为叛将宇文化及所弑，遂被洛阳官员拥立为皇帝，618年6月22日至619年5月23日在位，年号皇泰，是隋朝最后一位君主。他登基不久被官员王世充夺权，被迫禅位给王世充，并被王世充下令杀害，谥号隋恭帝。因其弟杨侑谥号也是隋恭帝，而唐朝官修的《隋书》仅认可杨侑为隋朝皇帝而不认可杨侗，为表区分，史书一般以登基前封号称杨侗为越王，或以年号称为皇泰主。");
            pEntries.Add("sui_yao_chong",
                "姚崇（651年—721年9月28日），原名元崇，后名元之，其后为了避唐玄宗的「开元」年号之讳，改名为姚崇，陕州硖石县人，唐朝宰相。姚崇以门荫入仕，被授与濮州司仓的职务。他于武周时期，升为兵部郎中。当时正值契丹侵扰河北，战事频仍，姚崇向武则天剖析形势，分辨利害，受到武则天赏识，擢升为侍郎。此卡侧重姚崇拜相后提出十事要说、整顿吏治并主持开元初政的宰相身份。");
            pEntries.Add("sui_yao_chong_blue",
                "姚崇（651年—721年9月28日），原名元崇，后名元之，其后为了避唐玄宗的「开元」年号之讳，改名为姚崇，陕州硖石县人，唐朝宰相。姚崇以门荫入仕，被授与濮州司仓的职务。他于武周时期，升为兵部郎中。当时正值契丹侵扰河北，战事频仍，姚崇向武则天剖析形势，分辨利害，受到武则天赏识，擢升为侍郎。此卡侧重姚崇历任地方官时救灾治蝗、积累行政经验并逐步进入中枢的阶段。");
            pEntries.Add("sui_yu_shinan",
                "虞世南（558年—638年7月11日），字伯施，越州余姚（今浙江省余姚市）人，唐朝官员、文学重臣。工书法，与欧阳询、褚遂良、薛稷合称“初唐四大家”。与欧阳询、褚遂良被日本学界合称为“初唐三大家”。编有《北堂书钞》一百六十卷，被誉为唐代四大类书之一，是中国现存最早的类书之一。");
            pEntries.Add("sui_yuchi_jingde",
                "尉（Yù）迟敬德（585年—658年12月26日），名融（后世史书载名恭），字敬德，以字行，墓志称其为河南洛阳人，史传称其为朔州善阳（今山西省朔州市）人，隋末唐初军事人物，凌烟阁二十四功臣之一，赠司徒兼并州都督，谥忠武，赐陪葬昭陵。出身将门世家，曾祖尉迟本真，担任北魏冠军将军，祖父尉迟梦都，担任北齐济州刺史，父亲尉迟伽担任过隋朝仪同等职务，隋炀帝大业末，敬德从军于高阳，以武勇称，累授朝散大夫。隋大业十三年刘武周起兵，收罗尉迟敬德为偏将，与宋金刚南侵，陷晋、浍二州。敬德破永安王李孝基，俘虏李孝基、独孤怀恩、唐俭等。");
            pEntries.Add("sui_yuwen_kai",
                "宇文恺（555年—612年11月6日），字安乐，北周、隋朝大臣，鲜卑人。许国公宇文贵之子，杞国公宇文忻弟。宇文恺生于西魏恭帝二年（555年），父亲宇文贵以弓马显名。三岁赐爵双泉伯，七岁晋封为安平郡公。");
            pEntries.Add("sui_zhang_jian",
                "张俭在唐太宗时期历任地方与边防职务，处理流民安置、城防修筑和生产恢复等事务。他以清廉谨慎受到朝廷信任，在边地治理中兼顾军事戒备和民政秩序。其任职经历体现贞观时期通过州县官员整合边疆、交通与户口的治理方式。");
            pEntries.Add("sui_zhang_jianzhi",
                "张柬之（625年—706年），字孟将，襄州襄阳人，曾与崔玄暐、桓彦范、敬晖等发动神龙革命，迫武则天禅让予唐中宗，唐朝因而复辟。后因得罪韦皇后、武三思，被贬至死。张柬之中进士后，任清源监察御史。永昌元年（689年）以贤良征试，擢为司马。");
            pEntries.Add("sui_zhang_jiuling",
                "张九龄由岭南科举入仕，开元年间官至宰相，以清正和文学才能受到唐玄宗重用。他主张谨慎封赏、重视边防，并在安禄山入朝时察觉其野心，建议依法处置但未被采纳。张九龄被李林甫排挤后贬任荆州，其诗文和直谏形象成为盛唐贤相传统的重要部分。");
            pEntries.Add("sui_zhang_renyuan",
                "张仁愿本名仁亶，是武周至唐中宗时期的边将与宰相，曾任幽州都督、朔方军总管等职。他趁突厥内乱北渡黄河，在河套北岸修筑东、中、西三座受降城，并设置烽候道路连接防区。三受降城压缩了突厥南下放牧和袭扰的空间，使唐朝北部边防在较长时间内保持主动，张仁愿也因军功封韩国公。");
            pEntries.Add("sui_zhang_sun_wuji",
                "长孙顺德，河南郡洛阳县（今河南省洛阳市东）人，初唐时期武将，长孙皇后和长孙无忌的族叔，凌烟阁二十四功臣之一。他的曾祖父北魏上党王长孙稚，祖父长孙士亮（长孙澄），北周秦州刺史，父亲长孙恺，在隋朝时任开府。长孙顺德在隋朝时任右勋卫，为逃避高句丽战役，前往太原，投靠李渊、李世民。大业十三年（617年），李世民派他以讨伐群盗为名，与刘弘基一同负责招募勇士，数日间达一万人，参与斩杀监视李渊的王威、高君雅等人。");
            pEntries.Add("sui_zhang_yi",
                "张易之（7世纪—705年），与其兄张昌宗（张宗之）是武则天的得力助手，听命女皇，行公禀明查，遍及宗室。705年张柬之等大臣发动神龙政变，驰禁军入宫，易之、宗之以逆臣罪被斩首。张氏兄弟是定州义丰县（今河北省安国市）人，为唐太宗宰相张行成的族孙，貌美而且善于音乐词律。万岁通天二年（697年），张宗之经太平公主推荐入宫侍奉武则天，张宗之随后推荐了弟弟张易之。");
            pEntries.Add("sui_zhang_yue",
                "张说历仕武周、唐中宗、睿宗和玄宗，三度拜相，是开元前期重要文臣。他主持军政文书、推动以募兵逐步替代府兵，并参与泰山封禅等国家礼仪。张说又以碑志和制诰见长，与苏颋并称“燕许大手笔”，对初盛唐文风影响显著。");
            pEntries.Add("tang_aidi",
                "唐哀帝李柷（zhù）（892年10月27日—908年3月26日），原名祚。唐昭宗第九子，生母何皇后。是唐朝最后一位皇帝，在904年－907年在位，在位3年，被废于朱温，朱温封李柷为济阴王，徙曹州（今山东省菏泽市曹县西北）。唐哀帝次年死，得年16岁，葬于温陵（今山东省菏泽市定陶区境内）。");
            pEntries.Add("tang_daizong",
                "唐代宗李豫（726年11月11日—779年6月10日），是唐肃宗李亨的庶长子。初名俶，小名冬郎，原封广平郡王，后改封广平王、楚王、成王，天可汗，唐朝皇帝，在位17年（762年5月18日－779年6月10日）。据《旧唐书》，代宗以开元十四年十二月十三日（727年1月9日）生于东都洛阳上阳宫。据《册府元龟》，代宗以开元十四年十月十三日（726年11月11日）生于东都上阳宫，且多年之中的十月份都有庆祝活动（上寿）。");
            pEntries.Add("tang_dezong",
                "李适（Guā或Kuò）（742年5月27日—805年2月25日），是唐代宗与睿真皇后所生长子，唐朝皇帝，779年6月12日－805年2月25日在位，在位26年，享寿62岁。李适于唐玄宗天宝元年四月十九日（742年5月27日）生于长安大内宫中，父亲时为广平郡王，生母沈氏是郡王妾室，李适出生后八个月便被封为奉节郡王。安史之乱中，嫡母崔氏家族失势，生母沈氏亦失踪。宝应元年（762年），父亲继位为唐代宗。");
            pEntries.Add("tang_gaozong",
                "唐高宗李治（628年7月21日—683年12月27日），小名雉奴，字为善，唐朝皇帝，唐太宗李世民第九子、嫡三子，母文德皇后长孙氏，和胞妹晋阳公主一样，唯一一对由太宗亲自抚养长大的亲生子女。唐高宗李治在位初年励精图治，号称「永徽之治」，而唐代的版图亦以高宗时为最大，领土面积为1237万平方公里，东起朝鲜半岛大同江以北及670年以前含括百济领土，西包咸海，北包贝加尔湖，南至越南承天顺化省。在位三十四年，于弘道元年（683年）崩于洛阳紫微宫贞观殿，终年五十五岁，葬于唐乾陵，庙号高宗，谥号天皇大圣大弘孝皇帝（初谥天皇大帝）。");
            pEntries.Add("tang_gaozu",
                "李渊（566年4月7日—635年6月25日），字叔德，唐朝开国皇帝，庙号高祖。李渊出身北周以来的关陇集团，父为隋朝唐国公李昞（一作李昺），母为独孤氏，家族与北周、隋两朝上层政治集团关系密切。七岁袭封唐国公，入隋后曾任千牛备身，后历任谯州、陇州、岐州刺史等职。617年，李渊在太原起兵，随后攻入大兴城，拥立杨侑为帝。");
            pEntries.Add("tang_jingzong",
                "唐敬宗李湛（809年7月22日—827年1月9日），唐朝皇帝。唐穆宗长子，15岁即位，824年－827年在位，在位3年，得年17岁。元和四年六月七日，生于东内（大明宫）之别殿，父亲唐穆宗时为遂王。元和十五年，祖父唐宪宗逝世，父亲继位，是为唐穆宗。");
            pEntries.Add("tang_muzong",
                "唐穆宗李恒（795年7月26日—824年2月25日），原名宥。唐宪宗第三子，母懿安皇后郭氏。唐德宗贞元十一年七月六日（795年7月26日）生于大明宫之别殿，初名李宥。当时的皇帝是他的曾祖父唐德宗，父亲唐宪宗时为广陵郡王，母亲郭氏为广陵郡王妃。");
            pEntries.Add("tang_ruizong",
                "唐睿宗李旦（662年6月22日—716年7月13日），唐高宗李治和武则天幼子，唐朝皇帝，曾用名李旭伦、李伦、武轮，他一生两继大统，两度禅位。两次登基，第一次为天后武氏（登基前的武则天）废唐中宗李显而继位，在位时间是文明元年至载初二年（684年2月27日－690年10月16日），后上表自行退位，禅让予母亲武则天；第二次是在唐隆政变诛除韦皇后及其党羽后复辟，在位时间是景云元年至延和元年（710年7月25日－712年9月8日），后退位，内禅予其子李隆基（唐玄宗）。李旦为唐高宗李治诸子之中排行第八，母为武则天，李弘、李贤、唐中宗李显都是其同母兄长，太平公主则为其同母妹妹。");
            pEntries.Add("tang_shang",
                "唐殇帝李重茂（695年—714年），中国唐朝第7任皇帝，为唐中宗李显幼子、唐玄宗李隆基堂弟。其于中宗景龙四年（710年）六月即位，在位仅十八日，后于玄宗开元二年（714年）七月逝世，终年十九岁，谥号殇皇帝，是唐朝在位时间最短的皇帝，也是唐朝两位没有庙号的皇帝之一。李重茂生于武周延载元年（695年），武周圣历三年（700年）封为北海郡王，神龙元年二月二十一日（705年3月20日）进封温王，授右卫大将军，兼遥领赠州大都督，没有到任。景龙四年（710年）中宗病逝后，景龙四年六月初二日（710年7月3日），韦后临朝，改元唐隆。");
            pEntries.Add("tang_shunzong",
                "唐顺宗李诵（761年2月21日—806年2月11日），唐德宗长子，唐朝皇帝，于公元805年在位180余日。上元二年（761年）阴历正月十二日（阳历761年2月21日），李诵生于长安之东内。当时他的高祖父唐玄宗李隆基作为太上皇仍在人世，被清人赵翼称之为“一堂五天子”（唐玄宗、唐肃宗、唐代宗、唐德宗、唐顺宗）。大历十四年（779年）其祖父唐代宗驾崩，唐德宗继位，六月，李诵进封宣王，十二月乙卯，立为皇太子。");
            pEntries.Add("tang_suzong",
                "唐肃宗李亨（711年10月19日—762年5月16日），唐朝皇帝，为唐玄宗李隆基第三子及第二位皇太子，母亲杨妃追尊元献皇太后，其于公元756至762年在位，共6年，其父唐玄宗此间仍然在世，被尊为太上皇。唐肃宗一生遍历种种惊心动魄，其出生前险些被父亲李隆基堕胎，成长过程中目睹父亲、兄长手足为了巩固权力勾心斗角、倾轧残害，也深度经历了唐朝由盛转衰的动荡国变——安史之乱。在乱局的白热化阶段，其随父亲玄宗出走避难，在都城长安之外登基称帝。肃宗即位后，指挥唐军进入反攻阶段，接连收复长安、洛阳两都，成效卓着，叛军领袖安禄山、史思明亦接连被杀，祸乱逐步被控制，皇室归朝。");
            pEntries.Add("tang_taizong",
                "李世民（598年—649年7月10日），唐高祖李渊次子，唐朝第二位皇帝。隋末随父起兵，参与统一战争。626年发动玄武门之变，杀太子李建成，受禅即位。在位23年（626年—649年），后世称贞观之治。");
            pEntries.Add("tang_wenzong",
                "李昂即唐文宗，即位后试图摆脱宦官对禁军和皇位继承的控制。他联合李训、郑注策划甘露之变，计划诛除仇士良等宦官，却因泄密而失败，大批朝臣遭到杀害。事变后文宗受制于神策军宦官，曾感叹自己不如汉献帝，最终在郁愤中去世。");
            pEntries.Add("tang_wuzong",
                "唐武宗李瀍（814年7月2日—846年4月22日）（「瀍」，拼音：chán，注音：ㄔㄢˊ，粤拼：cin4），临死前12天改名“炎”，唐穆宗的第五子和事实上的至少第九子，母韦贵妃。他是唐朝皇帝，在位时间是840年－846年，在位6年，享年33岁。唐武宗本来是唐敬宗、唐文宗的弟弟，被封为颍王。在宦官仇士良的操纵下，趁文宗病，矫诏立他为皇太弟，废原来的太子敬宗子李成美为陈王，武宗由此得以登基，并在仇士良的逼迫下赐死李成美、文宗杨贤妃和皇兄安王李溶。");
            pEntries.Add("tang_xianzong",
                "唐宪宗李纯（778年3月17日—820年2月14日），原名李淳，唐朝皇帝，805年－820年在位。唐宪宗透过宦官俱文珍等人的协助，迫使父亲唐顺宗让位予自己，即“永贞内禅”。即位后，曾一度讨平不服朝廷的藩镇，短暂终结藩镇割据，重新统一中国，史称“元和中兴”。");
            pEntries.Add("tang_xizong",
                "唐僖宗李儇（xuān）（862年6月8日—888年4月20日），唐懿宗第五子，唐朝第十九位皇帝（873年－888年在位）。他在位十五年间，爆发黄巢之乱（874年—884年），国都长安一度陷落，僖宗遂避难入蜀。其时唐朝中央权力日益衰微，宦官与藩镇互相角逐，朝政为之纷乱，国家分裂严重。死后谥号惠圣恭定孝皇帝，简称恭定皇帝。");
            pEntries.Add("tang_xuanzong_li_chen",
                "唐宣宗李忱（810年7月27日—859年9月10日），唐朝皇帝（846年－859年在位），初名怡，登基之前封为光王，在位十三年。唐宣宗是唐朝唯一以「皇太叔」身分继任为皇帝者，在位期间极力崇法唐太宗之为政德行，《旧唐书》及《资治通监》均对其给予极高的历史评价，认为其治下的「大中之治」造就了晚唐最后的太平；然而王夫之《读通监论》则给予其极低的评价，认为「唐之亡，宣宗亡之」。唐宣宗原名李怡，母亲郑氏原为镇海节度使李錡侍妾，元和二年（807年）十月李锜谋反失败遭腰斩后，郑氏以叛臣眷属的身分被没入掖廷，充为郭贵妃的侍儿，后来被唐宪宗临幸，于元和五年（810年）六月廿二日生李怡于大明宫，为宪宗第十三子，是唐穆宗李恒（在位四年）的弟弟，而在穆宗长子唐敬宗李湛（原景王，在位三年）、次子唐文宗李昂（原江王李涵，在位十三年）、及第八子安王李溶之弟的唐武宗李炎（原颍王李瀍，在位六年）三朝，皆为在位皇帝的叔父。");
            pEntries.Add("tang_xuanzong_li_longji",
                "唐玄宗李隆基（685年9月8日—762年5月3日），唐朝第9任皇帝，为唐睿宗李旦第三子，母为睿宗窦德妃，是唐朝及中国历史上最为着名的帝王之一，其前后共在位近44年（公元712年－756年），使用年号3个（先天、开元、天宝），后退居太上皇6年，享寿77岁，是唐朝在位最久与最长寿的皇帝，庙号玄宗，谥号至道大圣大明孝皇帝。由于后世的宋（赵玄朗）、清（玄烨）两朝皆有帝王名讳包含“玄”字，故改称其为唐明皇、唐元宗等，另有尊号开元圣文神武皇帝。唐玄宗是一位经历、政绩与评价较为复杂矛盾的皇帝。");
            pEntries.Add("tang_yizong",
                "唐懿宗李漼（cuǐ）（833年12月28日—873年8月15日），唐朝皇帝，859年至873年在位，在位14年，终年41岁。李漼初名温，唐宣宗李忱的长子。宣宗病死后，被宦官迎立为帝，是为唐懿宗，改元“咸通”。死后葬于简陵，谥号昭圣恭惠孝皇帝。");
            pEntries.Add("tang_zhaozong",
                "唐昭宗李晔（867年3月31日—904年9月22日），原名杰，立为皇太弟后改名为敏，即位后又改晔。是唐朝皇帝，888年－904年在位，他是唐懿宗第七子、唐僖宗的弟弟，即位后试图削除关中军阀，结果反被军阀挟制，曾三次出逃京师长安，最后被朱温劫持到洛阳杀害。生于咸通七年三月三十一日(867年)，是为唐懿宗第七子，母王氏。初名李杰，咸通十三年（872年）四月封寿王。");
            pEntries.Add("tang_zhongzong",
                "唐中宗李显（656年11月26日—710年7月3日），原名李哲，是唐朝皇帝，两次在位：第一次在位时间为684年1月3日－684年2月26日，第二次在位时间为705年2月23日－710年7月3日，两次在位合共五年半。唐中宗公元710年病逝，终年55岁，谥号大和大圣大昭孝皇帝（初谥孝和皇帝），葬于定陵。中宗的祖父（唐太宗）、父亲（唐高宗）、母亲（武则天）、弟弟（唐睿宗）、儿子（唐殇帝）和侄子（唐玄宗）皆为皇帝，这在中国史上极为少见。");
            pEntries.Add("wang_shichong",
                "王世充（？—621年），字行满，隋朝末年群雄之一，官居太尉、相国，封郑王。隋皇泰二年（619年），王世充在东都洛阳篡位，废皇泰主，自称「大郑皇帝」。唐朝武德四年（621年）败于李世民，被唐朝流放到巴蜀，遇仇而死。");
            pEntries.Add("xiao_xian",
                "萧铣（583年—621年），南兰陵郡兰陵县人，隋末天下大乱，于大业十三年（617年）称梁王，次年称帝。梁政权最终被唐朝所灭，萧铣被处决于长安。西梁宣帝曾孙，祖父萧岩为西梁明帝萧岿之弟，在西梁灭亡时逃亡陈朝，陈朝灭亡后被隋文帝所杀。萧铣少时家贫，605年杨广登基因隋炀帝之萧皇后外戚身份，被任命为罗县（今湖南湘阴东北）令。");
            pEntries.Add("xu_yuanlang",
                "徐圆朗（6世纪？—623年3月26日），隋末兖州人（今属山东）。大业十三年（617年）正月，鲁郡（今山东省兖州市）徐圆朗起义，后依附李密。武德二年七月（619年）徐圆朗归降唐朝。唐政府封他为鲁郡公，拜为兖州总管。");
            pEntries.Add("xue_ju",
                "薛举（6世纪—618年），河东郡汾阴县（今山西省运城市万荣县）人，其父薛汪时徙居兰州金城郡（今甘肃省兰州市），中国隋代末年群雄之一。大业十三年（617年）四月，薛举起兵反隋，自称西秦霸王，年号秦兴。大业十三年（617年）七月，薛举称帝，迁都秦州。武德元年（618年），薛举与唐军交战，在第一次浅水原之战大败秦王李世民，正欲乘胜直取长安，却突然病逝。");
            pEntries.Add("yuwen_huaji",
                "宇文化及（569年—619年3月21日），隋朝叛将，割据势力之一。原籍代郡武川（今内蒙古武川县西南），618年，他发动政变弑隋炀帝，自封为“丞相”。其后率精锐骁果军北上，却败于李密、李神通、窦建德。他自知即将败亡，想在生前称皇帝，于是毒杀隋帝杨浩，自称许帝。");
            pEntries.Add("zhou_wuzetian",
                "武曌，通称武则天、武后，原名不详，赐号武媚，亦称武媚娘、天后等，籍贯并州文水县（今山西省文水县），出生时间及出生地有争议，武周的开国皇帝、唐高宗的皇后，谥号则天顺圣皇后，尊号则天大圣皇帝，在帝位共14年余，是中国历史上唯一一位被广泛承认的女皇帝。武则天十四岁入宫为唐太宗才人，历经十二年不得升迁。唐高宗时复为昭仪，通过废除王皇后与萧淑妃，得以立为皇后（655年—683年），尊号天后，与天皇高宗并称“二圣”。由于高宗患有风眩症，660年11月武则天开始临朝当政，“自此内辅国政数十年，威势与帝无异”。");
            pEntries.Add("zhu_can",
                "朱粲（càn）（？—621年6月5日），隋末唐初亳州城父（今安徽省毫州市）人，朱粲最初为隋朝末期的县级官吏，615年随军讨伐变民途中逃跑后聚十万之众造反。转战安徽、湖北、陕西和四川等地杀戮无数，于618年在冠军县被马元规的军队打败，同年就东山再起，拥众20万，称楚帝，建立楚国。朱粲在以后的征战中因缺粮难以为继就烹煮人肉，朱粲后遭淮安豪族的反叛攻打，败退后向唐朝投降，被唐高祖李渊封为楚王，并派遣散骑常侍段确慰劳朱粲，不料却触犯朱粲，被朱粲烹食，朱粲旋即投奔王世充。");
            pEntries.Add("zhu_ci",
                "朱泚（cǐ）（742年—784年）。幽州昌平人（今北京昌平南），本为唐朝武将，后叛唐称帝。朱泚与其弟朱滔同为幽州节度使李怀仙部将。朱希彩杀李怀仙，继任节度使后，因同姓之故对其颇加信任。");
        }
    }
}
